END $access$;

DO $routines$
DECLARE item record; target text; role_name text;
BEGIN
  FOR item IN SELECT * FROM (VALUES
    ('app','allocate_journal_reference','p_organization_id uuid, p_transaction_date date',ARRAY[]::text[]),
    ('app','assign_posted_journal_reference','',ARRAY[]::text[]),
    ('app','capture_account_label_version','',ARRAY[]::text[]),
    ('app','account_label_at_entry','p_account_id uuid, p_entry_created_at timestamp with time zone',ARRAY['authenticated','service_role']::text[]),
    ('public','read_activity_journal','p_organization_id uuid, p_transaction_id uuid',ARRAY['authenticated']::text[]),
    ('app','search_transaction_page','p_organization_id uuid, p_search text, p_from_date date, p_to_date date, p_types transaction_type[], p_statuses transaction_status[], p_category_ids uuid[], p_account_ids uuid[], p_counterparty_ids uuid[], p_created_by_ids uuid[], p_tag_ids uuid[], p_min_amount_minor bigint, p_max_amount_minor bigint, p_sort text, p_direction text, p_limit integer, p_offset integer, p_sources transaction_source[]',ARRAY['authenticated']::text[]),
    ('public','dashboard_liquid_accounts','p_organization_id uuid',ARRAY['authenticated']::text[]),
    ('public','confirm_fx_revaluation','p_organization_id uuid, p_subledger_type text, p_control_account_id uuid, p_as_of_date date, p_reference text, p_rate_source text, p_rates jsonb, p_idempotency_key text',ARRAY['authenticated']::text[]),
    ('public','configure_fx_accounts','p_organization_id uuid, p_realized_gain uuid, p_realized_loss uuid, p_unrealized_gain uuid, p_unrealized_loss uuid',ARRAY['authenticated']::text[]),
    ('public','post_fx_open_item','p_organization_id uuid, p_subledger_type text, p_counterparty_id uuid, p_control_account_id uuid, p_offset_account_id uuid, p_document_date date, p_due_date date, p_reference text, p_currency_code character, p_original_minor bigint, p_recognition_rate numeric, p_rate_date date, p_rate_source text, p_rate_reference text, p_idempotency_key text',ARRAY['authenticated']::text[]),
    ('public','reverse_fx_open_item','p_organization_id uuid, p_item_id uuid, p_date date, p_reason text, p_idempotency_key text',ARRAY['authenticated']::text[]),
    ('public','post_fx_settlement','p_organization_id uuid, p_subledger_type text, p_counterparty_id uuid, p_control_account_id uuid, p_cash_account_id uuid, p_settlement_date date, p_reference text, p_settlement_currency character, p_gross_settlement_minor bigint, p_settlement_rate numeric, p_rate_date date, p_rate_source text, p_rate_reference text, p_allocations jsonb, p_idempotency_key text',ARRAY['authenticated']::text[]),
    ('public','reverse_fx_settlement','p_organization_id uuid, p_settlement_id uuid, p_date date, p_reason text, p_idempotency_key text',ARRAY['authenticated']::text[]),
    ('public','preview_fx_revaluation','p_organization_id uuid, p_subledger_type text, p_control_account_id uuid, p_as_of_date date, p_rates jsonb',ARRAY['authenticated']::text[]),
    ('public','reverse_fx_revaluation','p_organization_id uuid, p_batch_id uuid, p_date date, p_reason text, p_idempotency_key text',ARRAY['authenticated']::text[]),
    ('app','fx_item_position','p_organization_id uuid, p_item_id uuid, p_as_of date',ARRAY['service_role']::text[]),
    ('public','read_fx_workspace','p_organization_id uuid, p_subledger_type text, p_as_of_date date',ARRAY['authenticated']::text[]),
    ('app','eta_address_valid','p_address jsonb, p_issuer boolean',ARRAY['anon','authenticated','service_role']::text[]),
