    ('public','save_dimension_value','p_organization_id uuid, p_kind accounting_dimension_kind, p_code text, p_name text, p_description text, p_request_id uuid, p_dimension_value_id uuid',ARRAY['authenticated']::text[]),
    ('public','archive_dimension_value','p_organization_id uuid, p_dimension_value_id uuid, p_request_id uuid',ARRAY['authenticated']::text[]),
    ('public','set_account_dimension_policy','p_organization_id uuid, p_account_id uuid, p_kind accounting_dimension_kind, p_requirement dimension_requirement',ARRAY['authenticated']::text[]),
    ('public','set_draft_entry_dimension_allocations','p_organization_id uuid, p_entry_id uuid, p_allocations jsonb',ARRAY['authenticated']::text[]),
    ('public','read_dimension_workspace','p_organization_id uuid',ARRAY['authenticated']::text[]),
    ('public','report_by_accounting_dimension','p_organization_id uuid, p_report_kind text, p_dimension_kind accounting_dimension_kind, p_from_date date, p_to_date date, p_dimension_value_id uuid',ARRAY['authenticated']::text[]),
    ('public','post_egypt_vat_document','p_organization_id uuid, p_direction vat_direction, p_kind vat_document_kind, p_document_date date, p_tax_point_date date, p_reference text, p_taxable_base_minor bigint, p_base_account_id uuid, p_gross_account_id uuid, p_idempotency_key text, p_counterparty_id uuid, p_input_eligible boolean, p_reason text, p_adjusts_document_id uuid, p_rule_code text',ARRAY['authenticated']::text[]),
    ('public','configure_egypt_vat','p_organization_id uuid, p_registration_number text, p_effective_from date, p_output_vat_account_id uuid, p_input_vat_account_id uuid',ARRAY['authenticated']::text[]),
    ('public','reverse_egypt_vat_document','p_organization_id uuid, p_document_id uuid, p_document_date date, p_tax_point_date date, p_reason text, p_idempotency_key text',ARRAY['authenticated']::text[]),
    ('public','read_egypt_vat_report','p_organization_id uuid, p_from_date date, p_to_date date',ARRAY['authenticated']::text[]),
    ('public','read_egypt_vat_workspace','p_organization_id uuid, p_from_date date, p_to_date date',ARRAY['authenticated']::text[]),
    ('public','configure_inventory_source','p_organization_id uuid, p_source_key text, p_actor_id uuid, p_effective_from date, p_control_account_id uuid, p_cogs_account_id uuid, p_offset_account_id uuid',ARRAY['authenticated']::text[]),
    ('public','create_inventory_control_account','p_organization_id uuid, p_name text',ARRAY['authenticated']::text[]),
    ('public','ingest_inventory_fact','p_organization_id uuid, p_source_id uuid, p_fact jsonb',ARRAY['authenticated']::text[]),
    ('public','read_inventory_workspace','p_organization_id uuid, p_as_of_date date, p_offset integer, p_limit integer, p_fact_id uuid',ARRAY['authenticated']::text[])
  ) AS allowed(schema_name,routine_name,arguments,roles) LOOP
    IF EXISTS(SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
      WHERE n.nspname=item.schema_name AND p.proname=item.routine_name
        AND pg_get_function_identity_arguments(p.oid)=item.arguments) THEN
      target:=format('%I.%I(%s)',item.schema_name,item.routine_name,item.arguments);
      FOREACH role_name IN ARRAY item.roles LOOP
        EXECUTE format('GRANT EXECUTE ON ROUTINE %s TO %I',target,role_name);
      END LOOP;
      EXECUTE format('REVOKE EXECUTE ON ROUTINE %s FROM PUBLIC',target);
    END IF;
  END LOOP;
  FOR item IN SELECT p.oid::regprocedure AS signature FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace
    WHERE n.nspname=ANY(ARRAY['public','app']::text[]) AND p.prorettype IN ('trigger'::regtype,'event_trigger'::regtype)
      AND NOT EXISTS(SELECT 1 FROM pg_depend d WHERE d.classid='pg_proc'::regclass AND d.objid=p.oid AND d.deptype='e')
  LOOP EXECUTE format('REVOKE EXECUTE ON ROUTINE %s FROM PUBLIC,anon,authenticated',item.signature); END LOOP;
END $routines$;
NOTIFY pgrst,'reload schema';
COMMIT;
